## ---- 08: Reshaping `[time × maturity × path]` to `[path × time]`  (qmd line 255) -----

library(dnsr)

mats <- c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30)
yield_paths <- list()
for (i in seq_along(mats)) {
  yield_paths[[as.character(mats[i])]] <- t(sim$yields[, i, ])
}
str(yield_paths[["10"]])     # n_paths x n_months


## ---- 09: Constructing Reference Rates  (qmd line 268) --------------------------------

# Prime = 3M Treasury + 300 bp
yield_paths$PRIME <- yield_paths[["0.25"]] + 0.03

# SOFR ≈ short rate
yield_paths$SOFR  <- yield_paths[["0.25"]]

# 3M Libor (legacy)
yield_paths$LIBOR_3M <- yield_paths[["0.25"]] + 0.003


## ---- 10: Rate Floor Application  (qmd line 281) --------------------------------------

# Hard floor at zero
yield_paths_floored <- lapply(yield_paths, function(M) pmax(M, 0))

# Soft floor (smooth approximation)
soft_floor <- function(x, k = 100) log1p(exp(k * x)) / k
yield_paths_soft <- lapply(yield_paths, soft_floor)


## ---- 11: Scenario Mode (User Helper)  (qmd line 292) ---------------------------------

# Helper: deterministic shifted Prime paths (not in package — illustrative)
scenario_prime_paths <- function(base_path, shifts_bp = c(-50, -25, 0, 25, 50)) {
  n_months <- length(base_path)
  out <- matrix(NA_real_, nrow = length(shifts_bp), ncol = n_months)
  for (i in seq_along(shifts_bp)) {
    out[i, ] <- base_path + shifts_bp[i] / 10000
  }
  out
}

# oasr::extract_reference_rates pulls a chosen tenor from the rate-paths object
library(oasr)
prime_path <- extract_reference_rates(list(yield_paths = yield_paths),
                                      reference_key = "0.25")[1, ] + 0.03
scenarios  <- scenario_prime_paths(prime_path)
str(scenarios)


## ---- 12: Fan Chart Visualization  (qmd line 313) -------------------------------------

library(ggplot2)
library(dplyr)

ten_year <- yield_paths[["10"]]
fan_data <- apply(ten_year, 2, quantile,
                  probs = c(0.05, 0.25, 0.5, 0.75, 0.95)) %>%
  t() %>% as.data.frame() %>%
  # time grid has n_steps + 1 points, month 0 first
  mutate(month = seq_len(n()) - 1)

ggplot(fan_data, aes(x = month)) +
  geom_ribbon(aes(ymin = `5%`, ymax = `95%`), alpha = 0.2) +
  geom_ribbon(aes(ymin = `25%`, ymax = `75%`), alpha = 0.4) +
  geom_line(aes(y = `50%`)) +
  labs(x = "Month", y = "10Y Yield",
       title = "Fan chart: 10Y Treasury yield, simulated")


## ---- 13: Cross-Maturity Consistency Diagnostic  (qmd line 334) -----------------------

# 10Y - 2Y spread across paths at horizon = 5 yrs
library(ggplot2)
spread_5y <- yield_paths[["10"]][, 60] - yield_paths[["2"]][, 60]
ggplot(data.frame(spread_bps = spread_5y * 10000), aes(spread_bps)) +
  geom_histogram(bins = 30, fill = "steelblue", colour = "white") +
  labs(title = "10Y-2Y spread distribution at 5 years",
       x = "Spread (bps)", y = "Count") +
  theme_minimal()


